/**
 * 상황 맵 장면 콘텐츠 — 가짜 데이터. 값은 프로토타입 SITS(expr · rp) · SIT_LEARN(bank) · SIT_MIS + SIT_KO(flow) · SIT_MORE · SIT_QUIZ · SIT_Q0 그대로예요.
 * 맞는 API: 18 `/lessons/:id` (장면 콘텐츠 한 덩어리). 키 = 맵 데이터의 contentId ('travel-1' = 맵 id-장면 번호).
 * 새 장면 = 여기에 한 덩어리 + data/maps/situation-maps.json 의 장면 줄 하나. 화면은 저절로 생겨요.
 * (SIT_LEARN 의 patterns · dialogue · talk 는 v480 부터 장면 흐름에서 안 써서 옮기지 않았어요)
 * 이 파일은 프로토타입에서 뽑아 만든 거라 손으로 고치기보다 다시 뽑는 게 좋아요.
 */

/** [영어 표현, 뜻, 예문] */
export type Expr = [en: string, ko: string, example: string];
/** [영어, 한국어] (+ 1 = 마지막 말) */
export type Line = [en: string, ko: string] | [en: string, ko: string, last: 1];
/** 롤플레이 대본 (리스닝 룸 · 상황 퀴즈 말한 사람 이름에 써요) */
export type Roleplay = { who: string; c: string; title: string; intro: string; lines: Line[]; chips: string[] };
/** Word Bank: [예문, 단어, 뜻 빈칸 문장, 뜻] */
export type BankRow = [en: string, word: string, koBlank: string, ko: string];
/** 장면 롤플레이 한 순간: 직원 말 · 내가 할 일 · 레벨 0~4 문장(영어 · 한국어) */
export type Moment = { staff: [en: string, ko: string]; ko: string; lv: string[]; kos: string[] };
/** 미션: 제목 · 상황 · 미션 확인 정규식 */
export type Mission = Moment & { t: string; sit: string; re: string };
export type Twist = Moment & { k: string };
export type Flow = { who: string; role: string; c: string; arrive: Moment; mis: Mission[]; twist: Twist; end: [en: string, ko: string] };
/** 미션 뒤 이어지는 직원 질문: [영어, 한국어, 추천 답 3개] */
export type MoreQ = [en: string, ko: string, replies: string[]];
/** 상황 퀴즈 한 줄: [상황(한국어), 상대가 하는 말(없으면 null), 정답 문장, 정답 뜻, 빈칸 단어(없으면 null), 그럴듯하지만 틀린 말 2개, 어색한 직역 표현, 빈칸 오답 2개] */
export type QuizRow = [ctx: string, line: string | null, ans: string, ansKo: string, blank: string | null, near: string[], awkward: string, blankWrong: string[]];
/** Lv.0 왕기초: 단어 ['w', 한국어, 예문, 정답 단어, 오답 3개] · 문법 ['g', 문장 뜻, 빈칸 문장(___), 정답, 오답 3개, 문법 팁] */
export type Q0Row = ['w', ko: string, example: string, ans: string, wrong: string[]] | ['g', ko: string, sentence: string, ans: string, wrong: string[], tip: string];

export type SceneContent = { expr: Expr[]; rp: Roleplay; bank: BankRow[]; flow: Flow; more: MoreQ[]; quiz: QuizRow[]; q0: Q0Row[] };

